import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk, SendMessageParams} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

function createMockProvider(response: string): AIProvider {
  return {
    async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
      yield {type: 'text', text: response};
      yield {type: 'stop', stopReason: 'end_turn'};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

describe('beforeSession throws', () => {
  it('beforeSession throwing still propagates to caller as rejection', async () => {
    const beforeSessionError = new Error('beforeSession failed');
    const hooks: OrchestratorHooks = {
      beforeSession: async () => {
        throw beforeSessionError;
      },
    };

    const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});
    await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow('beforeSession failed');
  });

  it('onError fires when beforeSession throws', async () => {
    let onErrorCalled = false;
    let receivedError: Error | undefined;

    const hooks: OrchestratorHooks = {
      beforeSession: async () => {
        throw new Error('beforeSession failed');
      },
      onError: async (_session, error) => {
        onErrorCalled = true;
        receivedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});

    try {
      await orchestrator.processMessage(createSession('hello'));
    } catch (error) {
      // Error is expected to be caught
    }

    expect(onErrorCalled).toBe(true);
    expect(receivedError?.message).toBe('beforeSession failed');
  });

  it('afterSession fires when beforeSession throws', async () => {
    let afterSessionCalled = false;

    const hooks: OrchestratorHooks = {
      beforeSession: async () => {
        throw new Error('beforeSession failed');
      },
      afterSession: async () => {
        afterSessionCalled = true;
      },
    };

    const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});

    try {
      await orchestrator.processMessage(createSession('hello'));
    } catch (error) {
      // Error is expected to be caught
    }

    expect(afterSessionCalled).toBe(true);
  });

  it('onError and afterSession both fire when beforeSession throws', async () => {
    const callOrder: string[] = [];

    const hooks: OrchestratorHooks = {
      beforeSession: async () => {
        throw new Error('beforeSession failed');
      },
      onError: async () => {
        callOrder.push('onError');
      },
      afterSession: async () => {
        callOrder.push('afterSession');
      },
    };

    const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});

    try {
      await orchestrator.processMessage(createSession('hello'));
    } catch (error) {
      // Error is expected to be caught
    }

    expect(callOrder).toEqual(['onError', 'afterSession']);
  });
});

